#!/usr/bin/env node
// Generates a LOCAL-DEVELOPMENT-ONLY ECDSA P-256 key pair for the profile-attestation signer (a DIFFERENT key
// from the legacy scan-attestation dev key generated by generate-dev-signing-key.mjs — see
// workers/api/src/profileAttestationSigning.ts's header for why they are deliberately separate). This key is
// never production material, is written only to a file already covered by .gitignore, and must never be
// reused once a real production profile-attestation key exists.
//
// Usage: node workers/api/scripts/generate-dev-profile-attestation-key.mjs
// Then paste the printed lines into workers/api/.dev.vars (gitignored — see workers/api/.dev.vars.example).

import { writeFileSync, existsSync, readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import path from 'node:path'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const devVarsPath = path.join(__dirname, '..', '.dev.vars')
const PROFILE_KEY_PURPOSE = 'agentverify-profile-v1' // must equal packages/scanner/src/profileAttestation.ts's PROFILE_KEY_PURPOSE

async function main() {
  const pair = await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify'])
  const privateJwk = await crypto.subtle.exportKey('jwk', pair.privateKey)
  // DEV ONLY — never a production signing key. Regenerate any time; nothing depends on this specific key
  // surviving between local sessions. { kty, crv, x, y, d } is exactly what this signer's module reads.
  privateJwk.key_ops = ['sign']

  const publicJwk = await crypto.subtle.exportKey('jwk', pair.publicKey)
  const thumbprintMembers = { crv: publicJwk.crv, kty: publicJwk.kty, x: publicJwk.x, y: publicJwk.y }
  const canonical = JSON.stringify(thumbprintMembers, Object.keys(thumbprintMembers).sort())
  const digestBuf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(canonical))
  let binary = ''
  for (const b of new Uint8Array(digestBuf)) binary += String.fromCharCode(b)
  const keyId = btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')

  // Base64-encoded — sidesteps any ambiguity in how a given dotenv-style parser handles quotes/escaping around
  // embedded double quotes (matches the pattern generate-dev-signing-key.mjs already established).
  const lines = [
    `PROFILE_ATTESTATION_SIGNING_PRIVATE_KEY_JWK_B64=${Buffer.from(JSON.stringify(privateJwk)).toString('base64')}`,
    `PROFILE_ATTESTATION_ISSUER=agentverify-dev`,
    `PROFILE_ATTESTATION_KEY_PURPOSE=${PROFILE_KEY_PURPOSE}`,
    `PROFILE_ATTESTATION_EXPECTED_KEY_ID=${keyId}`,
  ]

  console.log('\n=== DEV-ONLY Agent Verify PROFILE-ATTESTATION signing key generated ===')
  console.log('This key is for LOCAL DEVELOPMENT ONLY. Never use it in production.')
  console.log(`keyId (RFC 7638 thumbprint): ${keyId}\n`)

  if (existsSync(devVarsPath)) {
    const existing = readFileSync(devVarsPath, 'utf8')
    if (existing.includes('PROFILE_ATTESTATION_SIGNING_PRIVATE_KEY_JWK')) {
      console.log(`workers/api/.dev.vars already has a profile-attestation signing key. Not overwriting.`)
      console.log('Delete the PROFILE_ATTESTATION_* lines from it first if you want to regenerate.\n')
      return
    }
    writeFileSync(devVarsPath, `${existing.trimEnd()}\n${lines.join('\n')}\n`)
  } else {
    writeFileSync(devVarsPath, `${lines.join('\n')}\n`)
  }
  console.log(`Written to ${devVarsPath} (gitignored, local only).`)
  console.log('Restart the API worker (or npm run review) to pick it up.\n')
}

main()
